// playwright.config.ts
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './e2e',
  fullyParallel: true,
  retries: 1,
  use: {
    baseURL: 'http://localhost:3000',
    // Always-on diagnostics: recorded for every test, pass or fail.
    trace: 'on',
    video: 'on',
    screenshot: 'on',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});

// e2e/dashboard.spec.ts
// ~30 tests live across this file and a handful of siblings
// (orders.spec.ts, settings.spec.ts, billing.spec.ts, ...), and every
// single one of them repeats the exact same beforeEach below.
import { test, expect } from '@playwright/test';

test.describe('Dashboard', () => {
  test.beforeEach(async ({ page }) => {
    // Real browser login before EVERY test, ~3s each.
    await page.goto('/login');
    await page.fill('#email', 'qa-user@example.com');
    await page.fill('#password', 'Password123!');
    await page.click('button[type="submit"]');
    await page.waitForURL('/dashboard');
  });

  test('shows the welcome banner', async ({ page }) => {
    await expect(page.getByText('Welcome back')).toBeVisible();
  });

  test('lists recent orders', async ({ page }) => {
    await expect(page.getByTestId('recent-orders')).toBeVisible();
  });

  test('shows the account balance widget', async ({ page }) => {
    await expect(page.getByTestId('balance-widget')).toBeVisible();
  });

  // ... ~27 more tests in this file and its siblings, each one
  // inheriting the same login-per-test beforeEach and the same
  // always-on trace/video/screenshot config above.
});

// e2e/auth.spec.ts
// The one spec that actually verifies the login flow itself.
test.describe('Login flow', () => {
  test('logs a user in and redirects to the dashboard', async ({ page }) => {
    await page.goto('/login');
    await page.fill('#email', 'qa-user@example.com');
    await page.fill('#password', 'Password123!');
    await page.click('button[type="submit"]');
    await page.waitForURL('/dashboard');
    await expect(page.getByText('Welcome back')).toBeVisible();
  });
});
